-- Phase 3 (part 1): Better Auth tables for SimplifyEU.
-- Email + password only (no OAuth yet). IDs are UUID to match existing uuid FKs.
-- Mirrors apps/web/src/db/auth-schema.ts (generated by @better-auth/cli).

BEGIN;

-- user ------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS "user" (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name          TEXT NOT NULL,
  email         TEXT NOT NULL UNIQUE,
  email_verified BOOLEAN NOT NULL DEFAULT false,
  image         TEXT,
  created_at    TIMESTAMP NOT NULL DEFAULT now(),
  updated_at    TIMESTAMP NOT NULL DEFAULT now()
);

-- session ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS session (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  expires_at  TIMESTAMP NOT NULL,
  token       TEXT NOT NULL UNIQUE,
  created_at  TIMESTAMP NOT NULL DEFAULT now(),
  updated_at  TIMESTAMP NOT NULL DEFAULT now(),
  ip_address  TEXT,
  user_agent  TEXT,
  user_id     UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS "session_userId_idx" ON session (user_id);

-- account ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS account (
  id                        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id                TEXT NOT NULL,
  provider_id               TEXT NOT NULL,
  user_id                   UUID NOT NULL REFERENCES "user"(id) ON DELETE CASCADE,
  access_token              TEXT,
  refresh_token             TEXT,
  id_token                  TEXT,
  access_token_expires_at   TIMESTAMP,
  refresh_token_expires_at  TIMESTAMP,
  scope                     TEXT,
  password                  TEXT,
  created_at                TIMESTAMP NOT NULL DEFAULT now(),
  updated_at                TIMESTAMP NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "account_userId_idx" ON account (user_id);

-- verification ----------------------------------------------------------------
CREATE TABLE IF NOT EXISTS verification (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  identifier  TEXT NOT NULL,
  value       TEXT NOT NULL,
  expires_at  TIMESTAMP NOT NULL,
  created_at  TIMESTAMP NOT NULL DEFAULT now(),
  updated_at  TIMESTAMP NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS "verification_identifier_idx" ON verification (identifier);

-- Link app `users` profile rows to Better Auth `user` rows (same id).
-- The user.create.after hook inserts users(id) = "user".id, so the profile row
-- always references a real auth user.
ALTER TABLE users DROP CONSTRAINT IF EXISTS users_id_fk;
ALTER TABLE users
  ADD CONSTRAINT users_id_fk
  FOREIGN KEY (id) REFERENCES "user"(id) ON DELETE CASCADE;

COMMIT;
